246	// RemoveCheckpointTrailers removes every whole Entire-Checkpoint trailer line
247	// whose ID drop selects, anywhere between the subject paragraph and a scissors
248	// line, and returns the new message with the IDs removed (nil when the
249	// message is unchanged). It does not try to reproduce git's trailer-block
250	// rules (mixed blocks, a "(cherry picked from ...)" note, custom comment
251	// characters): a line that is exactly a checkpoint trailer is one in every
252	// form git accepts, and leaving one behind would let an amend keep a deleted
253	// checkpoint alive. Indentation is ignored, since a squash message indents
254	// the squashed commits' messages. Prose that merely mentions an ID is not a
255	// whole trailer line and stays. Blank lines a removal leaves doubled are
256	// collapsed, and trailing blank lines are trimmed unless a scissors line
257	// follows; nothing at or below the scissors line is touched.
258	func RemoveCheckpointTrailers(message string, drop func(checkpointID.CheckpointID) bool) (string, []checkpointID.CheckpointID) {
259		lines := strings.Split(message, "\n")
260		bodyStart := subjectParagraphEnd(lines)
261		end := slices.IndexFunc(lines, func(line string) bool { return strings.Contains(line, scissorsMarker) })
262		hasScissors := end >= 0
263		if !hasScissors {
264			end = len(lines)
265		}
266		removeLine := make([]bool, end)
267		var removed []checkpointID.CheckpointID
268		for i := bodyStart; i < end; i++ {
269			match := checkpointTrailerLineRegex.FindStringSubmatch(strings.TrimSpace(lines[i]))
270			if match == nil {
271				continue
272			}
273			cpID, err := checkpointID.NewCheckpointID(match[1])
274			if err != nil || !drop(cpID) {
275				continue
276			}
277			removeLine[i] = true
278			if !slices.Contains(removed, cpID) {
279				removed = append(removed, cpID)
280			}
281		}
282		if len(removed) == 0 {
283			return message, nil
284		}
285		if hasScissors {
286			kept := keepLines(lines[:end], removeLine, false, false)
287			return strings.Join(append(kept, lines[end:]...), "\n"), removed
288		}
289		return strings.Join(keepLines(lines, removeLine, true, strings.HasSuffix(message, "\n")), "\n"), removed
290	}
