305	// keepLines drops the removed lines and collapses a blank line that a
306	// removal would leave doubled. With trimTrailing it also trims trailing blank
307	// lines, keeping the message's final newline.
308	func keepLines(lines []string, removeLine []bool, trimTrailing, endsWithNewline bool) []string {
309		kept := make([]string, 0, len(lines))
310		afterRemoval := false
311		for i, line := range lines {
312			if removeLine[i] {
313				afterRemoval = true
314				continue
315			}
316			blank := isBlankLine(line)
317			if blank && afterRemoval && len(kept) > 0 && isBlankLine(kept[len(kept)-1]) {
318				continue
319			}
320			if !blank {
321				afterRemoval = false
322			}
323			kept = append(kept, line)
324		}
325		if !trimTrailing {
326			return kept
327		}
328		for len(kept) > 0 && isBlankLine(kept[len(kept)-1]) {
329			kept = kept[:len(kept)-1]
330		}
331		if endsWithNewline {
332			kept = append(kept, "")
333		}
334		return kept
335	}
