268					slog.String("base_commit", truncateHash(state.BaseCommit)),
269				)
270				return nil
271			})
272			if mutErr != nil && !errors.Is(mutErr, ErrStateNotFound) {
273				logging.Warn(logCtx, "post-rewrite: failed to remap session linkage",
274					slog.String("session_id", sessionID),
275					slog.String("error", mutErr.Error()),
276				)
277			}
278		}
