283	func parsePostRewritePairs(r io.Reader) ([]rewritePair, error) {
284		scanner := bufio.NewScanner(r)
285		var pairs []rewritePair
286		for scanner.Scan() {
287			line := strings.TrimSpace(scanner.Text())
288			if line == "" {
289				continue
290			}
291			fields := strings.Fields(line)
292			if len(fields) < 2 {
293				return nil, fmt.Errorf("invalid post-rewrite mapping line: %q", line)
294			}
295			pairs = append(pairs, rewritePair{
296				OldSHA: fields[0],
297				NewSHA: fields[1],
298			})
299		}
300		if err := scanner.Err(); err != nil {
301			return nil, fmt.Errorf("scan post-rewrite input: %w", err)
302		}
303		return pairs, nil
304	}
