+		t.Errorf("HEAD's final trailer block should name the attached checkpoint %s, got %s (found=%v):\n%s",
+			state.LastCheckpointID, linked, ok, headCommit.Message)
+	}
+
+	store := cpkg.NewGitStore(repo, cpkg.DefaultV1Refs())
