+func TestExplainGenerate_BodyCheckpointLineIsNotATrailer(t *testing.T) {
+	repo, _ := runExplainAutoTestRepo(t)
+	commitHash := commitExplainBodyMention(t, repo)
+
+	tests := []struct {
+		name string
+		run  func(out, errOut io.Writer) error
+	}{
